/* Basic reset */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
body {
  font-family: Arial, Helvetica, sans-serif;
  line-height: 1.6;
  color: #333;
  background: #f4f4f4;
}
header {
  background: #35424a;
  color: #fff;
  padding: 20px 0;
  text-align: center;
}
nav ul {
  list-style: none;
  display: flex;
  justify-content: center;
  gap: 15px;
}
nav a {
  color: #fff;
  text-decoration: none;
  font-weight: bold;
}
main {
  max-width: 960px;
  margin: 20px auto;
  padding: 0 15px;
}
section {
  margin-bottom: 40px;
  background: #fff;
  padding: 20px;
  border-radius: 5px;
  box-shadow: 0 2px 5px rgba(0,0,0,0.1);
}
.project-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 20px;
}
.project-card {
  border: 1px solid #ddd;
  border-radius: 5px;
  overflow: hidden;
  background: #fff;
  display: flex;
  flex-direction: column;
}
.project-card img {
  width: 100%;
  height: 150px;
  object-fit: cover;
}
.project-card .content {
  padding: 15px;
  flex: 1;
}
.project-card h3 {
  margin-bottom: 10px;
}
form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
form input, form textarea {
  padding: 10px;
  border: 1px solid #ccc;
  border-radius: 4px;
  width: 100%;
}
form button {
  padding: 10px;
  background: #35424a;
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}
form button:hover {
  background: #45a049;
}
@media (max-width: 600px) {
  nav ul { flex-direction: column; }
}

