// Frontend script to fetch and render projects with optional search and tag filters

// Elements
const projectContainer = document.querySelector('.project-list');
const searchInput = document.createElement('input');
searchInput.type = 'text';
searchInput.placeholder = 'Search projects...';
searchInput.id = 'project-search';
searchInput.style.marginBottom = '10px';
searchInput.style.width = '100%';
searchInput.style.padding = '8px';
searchInput.style.boxSizing = 'border-box';
projectContainer.parentNode.insertBefore(searchInput, projectContainer);

let debounceTimer;
searchInput.addEventListener('input', () => {
  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(fetchAndRender, 300);
});

function fetchAndRender() {
  const query = searchInput.value.trim();
  const url = query ? `/api/projects?search=${encodeURIComponent(query)}` : '/api/projects';
  fetch(url)
    .then(res => res.json())
    .then(data => {
      renderProjects(data);
    })
    .catch(err => {
      console.error('Error fetching projects:', err);
      projectContainer.innerHTML = '<p>Failed to load projects.</p>';
    });
}

function renderProjects(projects) {
  projectContainer.innerHTML = '';
  if (projects.length === 0) {
    projectContainer.innerHTML = '<p>No projects match your criteria.</p>';
    return;
  }
  projects.forEach(p => {
    const card = document.createElement('div');
    card.className = 'project-card';
    card.innerHTML = `
      <img src="${p.image}" alt="${p.title}" />
      <div class="content">
        <h3>${p.title}</h3>
        <p>${p.description}</p>
        <a href="${p.link}" target="_blank">View Project</a>
      </div>
    `;
    projectContainer.appendChild(card);
  });
}

function handleContactForm(event) {
  event.preventDefault();
  const name = event.target.querySelector('input[type="text"]').value;
  const email = event.target.querySelector('input[type="email"]').value;
  const message = event.target.querySelector('textarea').value;
  alert(`Thank you, ${name}! Your message has been received.`);
  event.target.reset();
}

document.addEventListener('DOMContentLoaded', () => {
  fetchAndRender();
  const form = document.querySelector('form');
  form.addEventListener('submit', handleContactForm);
});

